import{_ as t}from"./chunks/feixing.8f86e254.js";import{D as h}from"./chunks/donate.3a95be8c.js";import{o as c,c as i,O as a,X as n}from"./chunks/framework.7fab6bae.js";import"./chunks/wcpay.d0e1a780.js";const g=n('<h1 id="紫微斗数四化" tabindex="-1">Tứ hóa trong Tử Vi Đẩu Số（紫微斗數四化） <a class="header-anchor" href="#紫微斗数四化" aria-label="Permalink to &quot;Tứ hóa trong Tử Vi Đẩu Số（紫微斗數四化）   {#紫微斗数四化}&quot;">​</a></h1><h2 id="前言" tabindex="-1">Lời mở đầu <a class="header-anchor" href="#前言" aria-label="Permalink to &quot;Lời mở đầu   {#前言}&quot;">​</a></h2><p>Chỉ có bốn dạng tứ hóa（四化星）, nhưng chúng tạo nên phần động của toàn bộ hệ thống Tử Vi Đẩu Số（紫微斗數）, như thêm một chiều để lá số phẳng trở nên có chiều sâu. Nếu tổ hợp sao biểu thị môi trường, thì tứ hóa biểu thị suy nghĩ và ý định. Có người xoay chuyển nghịch cảnh một cách ngoạn mục, cũng có người không làm được gì dù hoàn cảnh thuận lợi. Câu nói “người mạnh không than trách hoàn cảnh” nhấn mạnh chính sức mạnh nội tâm ấy.</p><p>Tứ hóa（四化星） không tồn tại độc lập mà gắn với các sao（星曜） khác, làm thay đổi tính chất của chúng. Có thể liên tưởng đến cacbon: mềm như than chì nhưng cũng có thể cứng như kim cương. Tác động làm tính chất của cacbon thay đổi được dùng ở đây như một phép ví von cho tứ hóa.</p><p>Cùng một sao（星曜） nhưng chịu tứ hóa（四化） khác nhau sẽ đem lại cảm nhận khác nhau. Đặc tính có thể trở nên năng động hơn hoặc trầm lặng hơn, mạnh mẽ hơn hoặc mềm yếu hơn. Không thể chỉ dựa vào đó để đánh giá tốt xấu. Một sao quá cứng rắn được làm mềm đi sẽ bớt góc cạnh, nhưng cũng có thể giảm sự kiên định và quyết đoán trong hành động.</p><p>Tứ hóa（四化） được chia thành hai nhóm lớn: tứ hóa theo vận hạn（運限四化） và tứ hóa theo cung（宮位四化）. Nhóm vận hạn gồm tứ hóa bản mệnh, đại hạn, lưu niên, lưu nguyệt, lưu nhật và lưu thì; mỗi loại được xác định bởi thiên can（天干） của chu kỳ tương ứng. Tứ hóa bản mệnh và đại hạn khác nhau tùy người, còn các loại vận hạn khác giống nhau cho mọi người tại cùng một thời điểm. Tứ hóa theo cung do can riêng của từng cung（宮干） tạo ra.</p><blockquote><p><em>Các bài viết trong loạt này do tác giả tự viết. Vui lòng ghi rõ nguồn khi đăng lại.</em></p></blockquote><div class="tip custom-block"><p class="custom-block-title">Mẹo</p><p>Cách hiểu của tôi về tứ hóa（四化） chưa chắc đã đúng. Hãy đọc với tinh thần phản biện, mạnh dạn đặt giả thuyết và kiểm chứng cẩn thận. Nếu thấy quan điểm sai trong bài, bạn có thể <a href="./../about">kết nối với tôi qua WeChat</a> để trao đổi.</p></div>',8),o=n('<h2 id="化禄" tabindex="-1">Lộc（化祿） <a class="header-anchor" href="#化禄" aria-label="Permalink to &quot;Lộc（化祿）   {#化禄}&quot;">​</a></h2><table class="star-card"><tr><td>ngũ hành（五行）</td><td>Thổ ⛰️</td><td>Ý tượng</td><td>Niềm vui, bận rộn, gia tăng, bao dung, nhiều</td></tr></table><p>Hóa Lộc（化祿） được viết tắt là <code>Lộc</code>（祿）. Đây là sức mạnh <code>gia tăng</code>, tức một sao trong một cung nhận thêm điều gì đó. Người ta thường coi lợi thế bẩm sinh này là hiển nhiên nên ít nhận ra nó. Vì vậy, họ có thể thiếu nhạy cảm với khó khăn của người khác, vì điều mình có sẵn lại là điều người khác đang thiếu.</p><p>Nhiều tài liệu cho rằng Hóa Lộc（化祿） có tác dụng giống <a href="./minor-star#禄存"><code>Lộc Tồn</code>（祿存）</a>, nhưng hai thứ khác nhau. Lộc Tồn（祿存） là “vốn”, tồn tại như một sao độc lập. Hóa Lộc phải gắn với sao khác và hoạt động như một “bộ khuếch đại”. Chẳng hạn, <a href="./major-star#破军星"><code>Phá Quân</code>（破軍）</a> biểu thị hao tổn, nên Phá Quân（破軍） Hóa Lộc làm tăng hao tổn. Đó là lý do một số tài liệu cho rằng trường hợp này không tốt. Tuy nhiên, mở rộng sản xuất hay kinh doanh cũng cần tăng chi phí, nên hao tổn tăng không nhất thiết là điều xấu.</p><p>Muốn hiểu Hóa Lộc（化祿）, trước tiên cần hiểu bản chất từng chính tinh（主星） để biết nó khuếch đại điều gì. Ví dụ, <a href="./major-star#天同星"><code>Thiên Đồng</code>（天同）</a> biểu thị phúc và sự hưởng thụ; Thiên Đồng Hóa Lộc làm tăng những đặc điểm đó. Điều này có vẻ tốt, nhưng cũng có thể khiến Thiên Đồng（天同）, vốn đã thiếu động lực, càng dễ an phận và không muốn vươn lên.</p><p>Sự gia tăng thường đem lại cảm giác vui, nên Hóa Lộc（化祿） cũng tạo niềm vui, ít nhất ngay lúc ấy. Có thể đó là cảm giác vẫn hài lòng dù đang mệt mỏi hay chịu khó khăn. Vì vậy, một số người luận giải cũng dè chừng Hóa Lộc khi tổ hợp sao không thuận: người đó có thể tự nguyện bỏ nhiều công sức nhưng cuối cùng không nhận được kết quả tích cực, dẫn đến phiền muộn.</p><h2 id="化权" tabindex="-1">Quyền（化權） <a class="header-anchor" href="#化权" aria-label="Permalink to &quot;Quyền（化權）   {#化权}&quot;">​</a></h2><table class="star-card"><tr><td>ngũ hành（五行）</td><td>Mộc 🪵</td><td>Ý tượng</td><td>Chiếm hữu, trách nhiệm, thực thi, quyền lực, lớn</td></tr></table><p>Hóa Quyền（化權） được viết tắt là <code>Quyền</code>（權）. Nó biểu thị sức mạnh <code>kiểm soát</code>, khả năng thực thi và quyền hạn. Cùng với Hóa Lộc（化祿） và Hóa Khoa（化科）, nó tạo thành <code>tam cát hóa</code>（三吉化）. Tuy nhiên, độc giả quen thuộc biết rằng tôi không xem điều gì là tuyệt đối tốt hay chắc chắn xấu: muốn nắm quyền kiểm soát điều gì thì cũng phải trả cái giá tương ứng.</p><p>Sức kiểm soát của Hóa Quyền（化權） hướng vào lĩnh vực của cung mà nó nằm tại. Ví dụ, Hóa Quyền ở <a href="./palace#官禄宫">cung <code>Quan Lộc</code>（官祿）</a> biểu thị mong muốn đạt thành tựu trong sự nghiệp và tự quản lý công việc mình phụ trách. Từ đó có thể thấy nó cũng biểu thị <code>tinh thần trách nhiệm</code>. Ngoài ra, Hóa Quyền còn tăng sự tự tin: lĩnh vực của cung ấy là nơi bạn tin mình có thể xử lý tốt.</p><p>Nhiều cách giải thích liên hệ Hóa Quyền（化權） với thăng chức, nhưng nó không nhất thiết có nghĩa là thăng chức; điều phải đảm nhiệm sẽ nhiều hơn. Hóa Quyền tăng khả năng hành động, và cung chứa nó là lĩnh vực chủ lá số muốn làm tốt. Vì vậy, nó biểu thị trách nhiệm.</p><p>Hóa Quyền（化權） cũng có thể tăng cảm giác áp lực và làm rõ những nét cứng rắn của sao. Khi nằm ở một cung lục thân khác（六親宮）, nó gợi ý sự chuyển giao quyền hạn. Nếu cố kiểm soát hoặc quản lý người mà cung ấy đại diện, dễ nảy sinh tranh chấp.</p><h2 id="化科" tabindex="-1">Khoa（化科） <a class="header-anchor" href="#化科" aria-label="Permalink to &quot;Khoa（化科）   {#化科}&quot;">​</a></h2><table class="star-card"><tr><td>ngũ hành（五行）</td><td>Thủy 🌊</td><td>Ý tượng</td><td>Hòa nhã, thể diện, quý nhân, danh tiếng, vừa phải</td></tr></table><p>Hóa Khoa（化科） được viết tắt là <code>Khoa</code>（科）. Nó thường được xem là sao có ảnh hưởng tiêu cực ít nhất trong Tử Vi Đẩu Số（紫微斗數）, và cách nhìn ấy có lý do. Cung có Hóa Khoa là lĩnh vực người đó cảm thấy được coi trọng và tự hào nhất, nên dễ muốn cho người khác thấy; điều này có thể khiến người khác ghen tị. “Khoe” ở đây không nhất thiết là khoe với bất kỳ ai gặp mặt, mà là niềm tự hào từ bên trong tự nhiên bộc lộ ra ngoài.</p><p>Cung này cũng đem lại sự an ủi tinh thần khi bạn mệt mỏi cả thể chất lẫn tâm trí, nên Hóa Khoa（化科） còn được gọi là sao quý nhân（貴人星）. Khi lĩnh vực ấy được thể hiện ra, người khác biết đến và danh tiếng hình thành. Ở đây tạm chưa xét đó là tiếng tốt hay tiếng xấu; ý chính là trở nên được biết đến rộng rãi.</p><p>Ai cũng có những việc muốn giữ riêng tư. Nếu Hóa Khoa（化科） khiến việc ấy được biết đến, đó chưa chắc là điều tốt với bạn. Ở cung lục thân（六親宮）, Hóa Khoa thường cho thấy người mà cung ấy đại diện có sự tu dưỡng và cách cư xử tốt. Ở cung lục sự（六事宮）, nó biểu thị lĩnh vực mà bạn thấy thoải mái không cần quá nhiều nỗ lực.</p><p>Vì dễ thấy thoải mái mà không cần cố gắng nhiều, người ta cũng khó bước ra khỏi vùng an toàn. Từ đó có cách ví “dòng chảy nhẹ nhàng mà lâu dài”, nghĩa là khá thuận, ít biến động. Xưa kia, lá số được đánh giá từ góc nhìn chủ lá số: mọi việc khiến họ vất vả hay tốn sức đều bị xem là không tốt, nên Hóa Khoa（化科） rất được ưa chuộng. Tuy nhiên, đây là cách nhìn phiến diện. Sự thuận lợi và ít chấp trước là ưu điểm, nhưng cũng có thể làm giảm tham vọng, chưa chắc tốt với người muốn đạt thành tựu lớn.</p><h2 id="化忌" tabindex="-1">Kỵ（化忌） <a class="header-anchor" href="#化忌" aria-label="Permalink to &quot;Kỵ（化忌）   {#化忌}&quot;">​</a></h2><table class="star-card"><tr><td>ngũ hành（五行）</td><td>Thủy 🌊</td><td>Ý tượng</td><td>Giằng co trong lòng, chú ý, bận tâm, rắc rối, ít</td></tr></table><p>Hóa Kỵ（化忌） được viết tắt là <code>Kỵ</code>（忌）. Chữ Hán 忌 gồm 己 ở trên, nghĩa là bản thân, và 心 ở dưới, nghĩa là tâm; qua đó biểu thị nội tâm của mình. Nếu Hóa Lộc（化祿） là tứ hóa ít được cảm nhận rõ nhất, thì Hóa Kỵ là dạng được cảm nhận mạnh nhất, vì càng quan tâm sâu thì càng dễ xao động. Theo cách nói truyền thống, Hóa Kỵ được xem là sát tinh（煞星） hoặc tai tinh（災星）, và thường được gộp với sát tinh dưới tên sát kỵ（煞忌）.</p><p>Lý do là cung có Hóa Kỵ（化忌） đại diện cho lĩnh vực người đó quan tâm và coi trọng nhất. Cảm nhận một cung tốt hay xấu rất chủ quan. Với lĩnh vực không quan tâm, tình hình dù kém cũng có thể không ảnh hưởng đến tâm trạng. Nhưng với lĩnh vực coi trọng, tốt thì muốn tốt hơn nữa, và chỉ một chút không ổn cũng được cảm nhận rất rõ.</p><p>Vì vậy, cung có Hóa Kỵ（化忌） là nơi <code>nỗi ám ảnh</code> mạnh, không thể chỉ gắn nhãn tốt hay xấu. Hóa Kỵ có thể là nguồn động lực: cảm thấy thiếu thì tìm cách bù đắp. Giống như đói khiến ta tìm thức ăn, Hóa Kỵ được ví với cảm giác nhu cầu chưa được đáp ứng ấy.</p><p>Nếu Hóa Kỵ（化忌） vào lục thân cung（六親宮）, những người và mối quan hệ ở cung đó rất quan trọng với bạn, nên bất đồng có thể gây tổn thương sâu sắc. Nếu vào lục sự cung（六事宮）, nó thể hiện sự chấp trước và cảm giác thiếu hụt. Ví dụ, người có Kỵ năm sinh（生年忌） ở cung Tài Bạch（財帛宮） có thể thấy thiếu tiền hoặc cơ hội kiếm tiền; chính cảm giác đó thúc đẩy họ làm việc bền bỉ và âm thầm tích lũy tài sản.</p><hr><div class="tip custom-block"><p class="custom-block-title">Mẹo</p><p>Tứ hóa（四化星） có thể được hiểu như những tác động tương tự “năng lượng”. Nhiều dạng cùng vào một cung sẽ ảnh hưởng lẫn nhau, nhưng tính chất riêng không mất đi. Khi <code>Lộc</code>（化祿） và <code>Kỵ</code>（化忌） cùng vào, niềm vui của Hóa Lộc và sự chấp trước của Hóa Kỵ cùng tồn tại, thậm chí làm sự chấp trước mạnh hơn. Nếu ví Hóa Lộc như trúng số, cả hai cùng xuất hiện giống cảm giác “trúng số nhưng mất vé để lĩnh thưởng”. Nhiều dạng tứ hóa tập trung vào một cung khiến bạn đặc biệt để ý mọi biến động và muốn chăm lo tốt lĩnh vực ấy.</p><ul><li><p>Hóa Lộc（化祿） và Hóa Kỵ（化忌）</p><p>Lĩnh vực này có thể đem lại niềm vui, nhưng cảm giác thiếu hụt khiến bạn không vui trọn vẹn. Bạn thấy giằng co: giữ nguyên thì chưa thỏa mãn, nhưng bỏ đi lại tiếc.</p></li><li><p>Hóa Lộc（化祿） và Hóa Quyền（化權）</p><p>Lĩnh vực này đem lại niềm vui và khiến bạn muốn làm chủ nó. Bạn có nhu cầu kiểm soát mạnh đối với việc của cung ấy và muốn đạt thành tựu ở đó.</p></li><li><p>Hóa Lộc（化祿） và Hóa Khoa（化科）</p><p>Lĩnh vực này đem lại niềm vui và sự tự hào, nên bạn thích thể hiện nó và tự tin hơn với những việc liên quan.</p></li><li><p>Hóa Quyền（化權） và Hóa Kỵ（化忌）</p><p>Bạn muốn kiểm soát lĩnh vực này nhưng lại thấy có thiếu sót, nên dễ đặt yêu cầu quá cao và nảy sinh mâu thuẫn.</p></li><li><p>Hóa Quyền（化權） và Hóa Khoa（化科）</p><p>Bạn vừa muốn kiểm soát vừa tự hào về lĩnh vực này, nên đặc biệt coi trọng danh tiếng liên quan đến nó.</p></li><li><p>Hóa Khoa（化科） và Hóa Kỵ（化忌）</p><p>Bạn cảm thấy lĩnh vực này đáng lẽ phải là niềm tự hào, nhưng lại có nhiều thiếu sót, nên âm thầm bỏ công sức vun đắp nó.</p></li></ul><p>Khi nhiều tứ hóa cùng xuất hiện, hãy tổng hợp đặc điểm riêng của chúng để phân tích; ở đây không trình bày thêm.</p></div><h2 id="飞星系统" tabindex="-1">Nguyên lý phi hóa <a class="header-anchor" href="#飞星系统" aria-label="Permalink to &quot;Nguyên lý phi hóa {#飞星系统}&quot;">​</a></h2><p>Như đã giới thiệu trong phần nhập môn, Tử Vi Đẩu Số（紫微斗數） nghiên cứu quan hệ giữa con người và môi trường. Trước phần về phi tinh（飛星） này, nội dung tập trung vào tác động của <code>môi trường bên ngoài</code> đến tâm lý và cảm xúc. Có người rất nhạy với thay đổi xung quanh, nhưng cũng có người ít nhạy hơn hoặc không quá để tâm đến những ảnh hưởng đó.</p><p>Phần này nói về <code>suy nghĩ</code> và <code>cảm nhận</code> của một người, phần lớn là chủ quan. Ví dụ, thu nhập một triệu nhân dân tệ trong năm có thể là con số lớn với nhiều người, nhưng người trước đây kiếm hai triệu nhân dân tệ mỗi năm vẫn có thể thấy năm nay tài vận kém. Họ đang so với trải nghiệm trước của chính mình, không phải một chuẩn chung cho mọi người.</p><p>Phi tinh（飛星） là khi <code>can của cung</code>（宮干） tại A khiến một sao trong cung B phát sinh tứ hóa. Ta nói cung A phi một tứ hóa sang cung B. Nếu sao ở B Hóa Kỵ（化忌）, tác động xung còn tới cung C, là đối cung của B. Khi đó có thể nói Kỵ của A xung C, như hình dưới.</p><img src="'+t+'" alt="四化飞星"><p>Dưới đây là các nguyên lý phi tinh（飛星）. Để ứng dụng vào luận giải, cần suy xét kỹ ý nghĩa của từng quan hệ:</p><ul><li><p>Cung A phi Hóa Lộc（化祿） vào cung B</p><p>Hóa Lộc（化祿） biểu thị sự gia tăng, nên có thể hiểu cung A làm tăng năng lượng của cung B. Nói đơn giản, A “thích” B, B là nguồn vui của A, hoặc B khiến A hài lòng.</p></li><li><p>Cung A phi Hóa Quyền（化權） vào cung B</p><p>Hóa Quyền（化權） biểu thị kiểm soát và trách nhiệm. Có thể hiểu A giao quyền hoặc trách nhiệm cho B, hoặc A dựa vào B. Cần phân biệt B là cung biểu thị người hay công việc. Nếu biểu thị công việc, A muốn kiểm soát lĩnh vực của B, vì vậy phải nhận thêm trách nhiệm và dành nhiều công sức hơn cho lĩnh vực đó.</p></li><li><p>Cung A phi Hóa Khoa（化科） vào cung B</p><p>Hóa Khoa（化科） biểu thị quý nhân và danh tiếng, nên cung A xem B là nguồn tự hào hoặc thể diện và thường muốn thể hiện những đặc điểm của B. Mở rộng ý nghĩa quý nhân（貴人）, A cũng xem B là lĩnh vực có thể giúp giải tỏa lo âu và tháo gỡ khó khăn.</p></li><li><p>Cung A phi Hóa Kỵ（化忌） vào cung B</p><p>Hóa Kỵ（化忌） biểu thị sự vướng bận và lo âu. A có thể thấy B là nguồn phiền muộn, hoặc khiến B phát sinh chấp trước. Nói đơn giản, A luôn để tâm đến B. Hóa Kỵ vào B còn tạo tác động <code>xung chiếu</code>（衝） đến cung C, là đối cung của B. Xung mang ý nghĩa chia lìa hoặc tách ra, nên trong cách luận này, C mới là nguồn gốc sâu hơn khiến A phiền muộn.</p></li><li><p>Cung A tự hóa（自化）</p><p>Tự hóa（自化） là cảm nhận chủ quan, không nhất thiết phản ánh tình hình thực tế, nên thường khó vượt qua. Tự Hóa Lộc（自化祿） cảm thấy năng lượng ở cung đã đủ và có thể không trân trọng nó. Tự Hóa Quyền（自化權） cảm thấy cần gánh trách nhiệm hoặc nắm thêm quyền nên bỏ nhiều công sức. Tự Hóa Khoa（自化科） có thể biểu thị sự tự ngưỡng mộ, còn Tự Hóa Kỵ（自化忌） là cảm giác tự tạo phiền muộn.</p></li></ul><div class="danger custom-block"><p class="custom-block-title">Lưu ý</p><p>Đối tượng của phi hóa theo can cung（宮干飛化） là chủ lá số, nên kết quả phải được nhìn từ góc độ của người đó. Một việc được số đông xem là tốt vẫn có thể gây phiền muộn cho cá nhân. Hiểu phi tinh（飛星） giúp nhận ra khác biệt giữa cảm nhận bên trong và hoàn cảnh bên ngoài, điều chỉnh cảm xúc và tham khảo khi quyết định. Khi hai người trong một mối quan hệ hiểu lầm nhau, phân tích phi tinh của đối phương có thể giúp tháo gỡ nhanh hơn. Tuy nhiên, cách này cũng có nguy cơ lớn tạo ra hiểu lầm mới, nên cần dùng thận trọng.</p></div><h2 id="十天干四化表" tabindex="-1">Bảng tứ hóa theo mười thiên can <a class="header-anchor" href="#十天干四化表" aria-label="Permalink to &quot;Bảng tứ hóa theo mười thiên can {#十天干四化表}&quot;">​</a></h2><p>Bảng tứ hóa（四化） theo thiên can（天干） có khác biệt giữa các trường phái. Thư viện mã nguồn mở của tôi lấy Tử Vi Đẩu Số Toàn Thư（紫微斗數全書）, gắn với Trần Hy Di（陳希夷）, làm chuẩn, nên ở đây chỉ trình bày bảng đó. Tôi chưa quen và chưa có kinh nghiệm dùng bảng của các trường phái khác; bạn có thể tự tìm hiểu thêm. Nếu có bảng của trường phái khác cùng nguồn trích dẫn và muốn bổ sung vào tài liệu, hãy <a href="./../about#怎么联系我❓">liên hệ tôi</a>.</p><table><thead><tr><th>thiên can（天干）</th><th>Lộc（祿）</th><th>Quyền（權）</th><th>Khoa（科）</th><th>Kỵ（忌）</th></tr></thead><tbody><tr><td>Giáp（甲）</td><td>Liêm Trinh（廉貞）</td><td>Phá Quân（破軍）</td><td>Vũ Khúc（武曲）</td><td>Thái Dương（太陽）</td></tr><tr><td>Ất（乙）</td><td>Thiên Cơ（天機）</td><td>Thiên Lương（天梁）</td><td>Tử Vi（紫微）</td><td>Thái Âm（太陰）</td></tr><tr><td>Bính（丙）</td><td>Thiên Đồng（天同）</td><td>Thiên Cơ（天機）</td><td>Văn Xương（文昌）</td><td>Liêm Trinh（廉貞）</td></tr><tr><td>Đinh（丁）</td><td>Thái Âm（太陰）</td><td>Thiên Đồng（天同）</td><td>Thiên Cơ（天機）</td><td>Cự Môn（巨門）</td></tr><tr><td>Mậu（戊）</td><td>Tham Lang（貪狼）</td><td>Thái Âm（太陰）</td><td>Hữu Bật（右弼）</td><td>Thiên Cơ（天機）</td></tr><tr><td>Kỷ（己）</td><td>Vũ Khúc（武曲）</td><td>Tham Lang（貪狼）</td><td>Thiên Lương（天梁）</td><td>Văn Khúc（文曲）</td></tr><tr><td>Canh（庚）</td><td>Thái Dương（太陽）</td><td>Vũ Khúc（武曲）</td><td>Thái Âm（太陰）</td><td>Thiên Đồng（天同）</td></tr><tr><td>Tân（辛）</td><td>Cự Môn（巨門）</td><td>Thái Dương（太陽）</td><td>Văn Khúc（文曲）</td><td>Văn Xương（文昌）</td></tr><tr><td>Nhâm（壬）</td><td>Thiên Lương（天梁）</td><td>Tử Vi（紫微）</td><td>Tả Phù（左輔）</td><td>Vũ Khúc（武曲）</td></tr><tr><td>Quý（癸）</td><td>Phá Quân（破軍）</td><td>Cự Môn（巨門）</td><td>Thái Âm（太陰）</td><td>Tham Lang（貪狼）</td></tr></tbody></table>',37),v=JSON.parse('{"title":"Tứ hóa trong Tử Vi: Hóa Lộc, Quyền, Khoa và Kỵ","description":"Tìm hiểu tứ hóa trong Tử Vi Đẩu Số và cách tứ hóa thể hiện suy nghĩ, ý định, tạo nên phần động của lá số.","frontmatter":{"title":"Tứ hóa trong Tử Vi: Hóa Lộc, Quyền, Khoa và Kỵ","description":"Tìm hiểu tứ hóa trong Tử Vi Đẩu Số và cách tứ hóa thể hiện suy nghĩ, ý định, tạo nên phần động của lá số.","head":[["link",{"rel":"canonical","href":"https://iztro.com/vi_VN/learn/mutagen"}],["link",{"rel":"alternate","hreflang":"zh-CN","href":"https://iztro.com/learn/mutagen"}],["link",{"rel":"alternate","hreflang":"zh-TW","href":"https://iztro.com/zh_TW/learn/mutagen"}],["link",{"rel":"alternate","hreflang":"en-US","href":"https://iztro.com/en_US/learn/mutagen"}],["link",{"rel":"alternate","hreflang":"ko-KR","href":"https://iztro.com/ko_KR/learn/mutagen"}],["link",{"rel":"alternate","hreflang":"ja-JP","href":"https://iztro.com/ja_JP/learn/mutagen"}],["link",{"rel":"alternate","hreflang":"vi-VN","href":"https://iztro.com/vi_VN/learn/mutagen"}],["link",{"rel":"alternate","hreflang":"x-default","href":"https://iztro.com/learn/mutagen"}],["meta",{"name":"robots","content":"max-image-preview:large"}],["meta",{"property":"og:type","content":"website"}],["meta",{"property":"og:site_name","content":"紫微研习社"}],["meta",{"property":"og:title","content":"Tứ hóa trong Tử Vi: Hóa Lộc, Quyền, Khoa và Kỵ | 紫微研习社"}],["meta",{"property":"og:description","content":"Tìm hiểu tứ hóa trong Tử Vi Đẩu Số và cách tứ hóa thể hiện suy nghĩ, ý định, tạo nên phần động của lá số."}],["meta",{"property":"og:url","content":"https://iztro.com/vi_VN/learn/mutagen"}],["meta",{"property":"og:locale","content":"vi_VN"}],["meta",{"property":"og:locale:alternate","content":"zh_CN"}],["meta",{"property":"og:locale:alternate","content":"zh_TW"}],["meta",{"property":"og:locale:alternate","content":"en_US"}],["meta",{"property":"og:locale:alternate","content":"ko_KR"}],["meta",{"property":"og:locale:alternate","content":"ja_JP"}],["meta",{"property":"og:image","content":"https://iztro.com/static/home_img.png"}],["meta",{"property":"og:image:width","content":"850"}],["meta",{"property":"og:image:height","content":"850"}],["meta",{"property":"og:image:alt","content":"紫微研习社"}],["meta",{"name":"twitter:card","content":"summary"}],["meta",{"name":"twitter:title","content":"Tứ hóa trong Tử Vi: Hóa Lộc, Quyền, Khoa và Kỵ | 紫微研习社"}],["meta",{"name":"twitter:description","content":"Tìm hiểu tứ hóa trong Tử Vi Đẩu Số và cách tứ hóa thể hiện suy nghĩ, ý định, tạo nên phần động của lá số."}],["meta",{"name":"twitter:image","content":"https://iztro.com/static/home_img.png"}],["meta",{"name":"twitter:image:alt","content":"紫微研习社"}],["script",{"type":"application/ld+json"},"{\\"@context\\":\\"https://schema.org\\",\\"@graph\\":[{\\"@type\\":\\"WebPage\\",\\"@id\\":\\"https://iztro.com/vi_VN/learn/mutagen#webpage\\",\\"url\\":\\"https://iztro.com/vi_VN/learn/mutagen\\",\\"name\\":\\"Tứ hóa trong Tử Vi: Hóa Lộc, Quyền, Khoa và Kỵ | 紫微研习社\\",\\"description\\":\\"Tìm hiểu tứ hóa trong Tử Vi Đẩu Số và cách tứ hóa thể hiện suy nghĩ, ý định, tạo nên phần động của lá số.\\",\\"inLanguage\\":\\"vi-VN\\",\\"isPartOf\\":{\\"@id\\":\\"https://iztro.com/#website\\"},\\"breadcrumb\\":{\\"@id\\":\\"https://iztro.com/vi_VN/learn/mutagen#breadcrumb\\"}},{\\"@type\\":\\"BreadcrumbList\\",\\"@id\\":\\"https://iztro.com/vi_VN/learn/mutagen#breadcrumb\\",\\"itemListElement\\":[{\\"@type\\":\\"ListItem\\",\\"position\\":1,\\"name\\":\\"紫微研习社\\",\\"item\\":\\"https://iztro.com/vi_VN/\\"},{\\"@type\\":\\"ListItem\\",\\"position\\":2,\\"name\\":\\"Tứ hóa trong Tử Vi: Hóa Lộc, Quyền, Khoa và Kỵ\\",\\"item\\":\\"https://iztro.com/vi_VN/learn/mutagen\\"}]}]}"]]},"headers":[],"relativePath":"vi_VN/learn/mutagen.md","filePath":"vi_VN/learn/mutagen.md"}'),u={name:"vi_VN/learn/mutagen.md"},y=Object.assign(u,{setup(m){return(e,r)=>(c(),i("div",null,[g,a(h),o]))}});export{v as __pageData,y as default};
